.flex { display: flex; flex-direction: row; gap: var(--flex-gap, 0); min-width: 0; }
.flex-inline { display: inline-flex; }
.flex-wrap { flex-wrap: wrap; }
.flex[data-direction="column"] { flex-direction: column; }
.flex[data-direction="row-reverse"] { flex-direction: row-reverse; }
.flex[data-direction="column-reverse"] { flex-direction: column-reverse; }
.flex[data-align="start"] { align-items: flex-start; }
.flex[data-align="center"] { align-items: center; }
.flex[data-align="end"] { align-items: flex-end; }
.flex[data-align="stretch"] { align-items: stretch; }
.flex[data-align="baseline"] { align-items: baseline; }
